// Writes one observational review to reports/<slug>/: review.json (the Review type, validated before
// it is written), sessions.json, outcomes.json and review.md. See docs/DESIGN.md §"Data model" and §"Review".
import { mkdirSync, writeFileSync } from "node:fs";
import { basename, join } from "node:path";
import type { EvidenceLevel, Outcome, Review, ReviewLabel, Session } from "../types.ts";

/** Keys of the Review type in src/types.ts. Kept in step by the `satisfies Review` check in tests. */
export const REVIEW_KEYS = [
  "id",
  "repo",
  "created_at",
  "label",
  "suspect",
  "odds_ratio",
  "ci95",
  "p_value",
  "evidence_level",
] as const;

const LABELS: readonly ReviewLabel[] = ["suspect", "no_suspect", "insufficient_data"];
const EVIDENCE: readonly EvidenceLevel[] = ["A", "B", "C"];

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
const isFiniteNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);

/** "owner/name" for a GitHub URL, otherwise the last path segment. */
export function repoLabel(repo: string): string {
  const trimmed = repo.trim();
  const remote = /github\.com[:/]([^/]+)\/([^/]+?)(?:\.git)?\/?$/.exec(trimmed);
  if (remote) return `${remote[1]}/${remote[2]}`;
  return basename(trimmed.replace(/\/+$/, "").replace(/\.git$/, ""));
}

/** Directory name under reports/: "owner__name" for GitHub repos (the web app's lookup form), else the basename. */
export function reviewSlug(repo: string): string {
  return repoLabel(repo).replace("/", "__").replace(/[^A-Za-z0-9._-]+/g, "-");
}

/** Lists every way `value` fails the Review type. An empty list means it validates. */
export function validateReview(value: unknown): string[] {
  if (!isRecord(value)) return ["review must be an object"];
  const errs: string[] = [];
  for (const k of REVIEW_KEYS) if (!(k in value)) errs.push(`missing ${k}`);
  for (const k of Object.keys(value)) if (!(REVIEW_KEYS as readonly string[]).includes(k)) errs.push(`unexpected key ${k}`);

  for (const k of ["id", "repo", "created_at"] as const) {
    if (typeof value[k] !== "string" || value[k] === "") errs.push(`${k} must be a non-empty string`);
  }
  if (typeof value.created_at === "string" && Number.isNaN(Date.parse(value.created_at))) errs.push("created_at is not a date");

  const label = value.label;
  if (!(LABELS as readonly unknown[]).includes(label)) errs.push(`label must be one of ${LABELS.join(", ")}`);
  if (label === "suspect") {
    if (typeof value.suspect !== "string" || value.suspect === "") errs.push("suspect must name a setup when label is suspect");
    if (!isFiniteNum(value.odds_ratio)) errs.push("odds_ratio must be a number when label is suspect");
    if (!Array.isArray(value.ci95)) errs.push("ci95 must be set when label is suspect");
    if (!isFiniteNum(value.p_value)) errs.push("p_value must be a number when label is suspect");
  } else if (value.suspect !== null) {
    errs.push("suspect must be null unless label is suspect");
  }

  if (value.odds_ratio !== null && !(isFiniteNum(value.odds_ratio) && value.odds_ratio >= 0)) {
    errs.push("odds_ratio must be null or a number >= 0");
  }
  const ci = value.ci95;
  if (ci !== null) {
    const ok = Array.isArray(ci) && ci.length === 2 && ci.every(isFiniteNum) && ci[0]! <= ci[1]!;
    if (!ok) errs.push("ci95 must be null or [low, high] with low <= high");
  }
  if (value.p_value !== null && !(isFiniteNum(value.p_value) && value.p_value >= 0 && value.p_value <= 1)) {
    errs.push("p_value must be null or a number in [0, 1]");
  }
  if (!(EVIDENCE as readonly unknown[]).includes(value.evidence_level)) errs.push("evidence_level must be A, B or C");
  return errs;
}

/** Per-setup numbers for review.md. Rates are null when no mature session supports them. */
export interface SetupSummary {
  setup_id: string;
  label: string;
  sessions: number;
  mature: number;
  spend_usd: number;
  unpriced: number;
  /** Mean survival over mature sessions. */
  survival: number | null;
  /** Share of mature sessions that were reverted. */
  reverted: number | null;
  /** Mean human rework share over mature sessions. */
  rework_human: number | null;
  /** Share of mature sessions that needed exactly one user prompt. */
  unattended: number | null;
}

const mean = (xs: number[]): number | null => (xs.length === 0 ? null : xs.reduce((a, b) => a + b, 0) / xs.length);

/** Groups sessions by setup_id. Sessions with no setup are left out; the caller counts them. */
export function summarizeSetups(sessions: Session[], outcomes: Outcome[]): SetupSummary[] {
  const byId = new Map<string, Outcome>(outcomes.map((o) => [o.session_id, o]));
  const groups = new Map<string, Session[]>();
  for (const s of sessions) {
    if (s.setup_id === null) continue;
    (groups.get(s.setup_id) ?? groups.set(s.setup_id, []).get(s.setup_id)!).push(s);
  }
  return [...groups]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([setup_id, group]) => {
      const outs = group.map((s) => byId.get(s.id)).filter((o): o is Outcome => o?.status === "mature");
      const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0);
      const survival = outs.map((o) => o.survival).filter((x): x is number => x !== null);
      const reverted = outs.map((o) => o.reverted).filter((x): x is boolean => x !== null);
      const human = outs.map((o) => o.rework_human).filter((x): x is number => x !== null);
      const unattended = outs.map((o) => o.unattended).filter((x): x is boolean => x !== null);
      const priced = group.map((s) => s.cost_usd).filter((x): x is number => x !== null);
      const first = group[0]!;
      return {
        setup_id,
        label: `${first.harness} · ${first.model}`,
        sessions: group.length,
        mature: outs.length,
        spend_usd: sum(priced),
        unpriced: group.length - priced.length,
        survival: mean(survival),
        reverted: reverted.length === 0 ? null : reverted.filter(Boolean).length / reverted.length,
        rework_human: mean(human),
        unattended: unattended.length === 0 ? null : unattended.filter(Boolean).length / unattended.length,
      };
    });
}

export interface ReviewReport {
  review: Review;
  /** Why the label is what it is, printed under the summary. */
  note: string;
  /** Sessions with setup_id and cost_usd filled in. */
  sessions: Session[];
  outcomes: Outcome[];
  /** Bullet lines for the notes section of review.md. */
  notes: string[];
}

const pct = (x: number | null) => (x === null ? "—" : `${(100 * x).toFixed(1)}%`);
const usd = (x: number) => `$${x.toFixed(2)}`;

export function renderReviewMarkdown(report: ReviewReport): string {
  const { review, note, notes } = report;
  const rows = summarizeSetups(report.sessions, report.outcomes);
  const lines = [
    `# Review: ${review.repo}`,
    "",
    `- Review id: \`${review.id}\``,
    `- Created: ${review.created_at}`,
    `- Evidence level: ${review.evidence_level} (observational)`,
    `- Label: \`${review.label}\``,
    `- Suspect: ${review.suspect ?? "none"}`,
    "",
    note,
    "",
    "## Setups",
    "",
    "| Setup | Harness · model | Sessions | Mature | Spend | Survival | Reverted | Rework (human) | Unattended |",
    "| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ...rows.map(
      (r) =>
        `| \`${r.setup_id}\` | ${r.label} | ${r.sessions} | ${r.mature} | ${usd(r.spend_usd)}${r.unpriced ? ` (${r.unpriced} unpriced)` : ""} | ${pct(r.survival)} | ${pct(r.reverted)} | ${pct(r.rework_human)} | ${pct(r.unattended)} |`,
    ),
    "",
    "## Notes",
    "",
    ...(notes.length ? notes.map((n) => `- ${n}`) : ["- none"]),
    "",
  ];
  return lines.join("\n");
}

const json = (v: unknown) => JSON.stringify(v, null, 2) + "\n";

/**
 * Writes the four report files into `outDir`. Throws, and writes nothing, when review.json fails validation.
 * Returns the paths written.
 */
export function writeReview(outDir: string, report: ReviewReport): string[] {
  const problems = validateReview(report.review);
  if (problems.length) throw new Error(`review.json does not validate: ${problems.join("; ")}`);
  mkdirSync(outDir, { recursive: true });
  const files: [string, string][] = [
    ["review.json", json(report.review)],
    ["sessions.json", json(report.sessions)],
    ["outcomes.json", json(report.outcomes)],
    ["review.md", renderReviewMarkdown(report)],
  ];
  return files.map(([name, body]) => {
    const path = join(outDir, name);
    writeFileSync(path, body);
    return path;
  });
}
// `roster review <repo> --observational`: fetch → parse → identify → score, then reports/<slug>/.
// Every stage is a TOOL span inside one WORKFLOW review span (DESIGN.md §"Observability (neatlogs)").
import { join, resolve } from "node:path";
import type { Command } from "../cli.ts";
import { priceSession } from "../price/index.ts";
import { flushObs, initObs, setSession, withSpan } from "../obs/index.ts";
import { fetchCheckpoints } from "../ingest/fetch.ts";
import { type ParsedSession, parseCheckpoints } from "../ingest/parse.ts";
import { type Identity, identify, inferenceAccuracy } from "../identity/index.ts";
import { survival } from "../score/survival.ts";
import { reverted } from "../score/revert.ts";
import { rework } from "../score/rework.ts";
import { repoLabel, reviewSlug, type ReviewReport, writeReview } from "../review/export.ts";
import type { Outcome, Review, Session } from "../types.ts";

export const DEFAULT_CACHE = ".roster/cache";
/** Mature = at least this many first-parent commits after the session's commit, and this many seconds older than HEAD. */
export const MIN_DEPTH = 5;
export const MIN_AGE_S = 6 * 3600;

const STAGES = ["fetch", "parse", "identify", "score"] as const;
type Stage = (typeof STAGES)[number];

const USAGE = `usage: roster review <repo> --observational [--out <dir>] [--cache <dir>]

  <repo>            a git URL or a local path to a repo that has Entire checkpoints
  --observational   score sessions that already exist (evidence level A). Required for now.
  --out <dir>       where to write review.json, review.md, sessions.json and outcomes.json
                    (default reports/<slug>)
  --cache <dir>     fetch cache (default ${DEFAULT_CACHE})`;

export interface ReviewArgs {
  repo: string;
  out: string | undefined;
  cache: string;
}

/** Thrown for bad arguments. The CLI prints the message and exits 2. */
export class UsageError extends Error {}

/** Parses the arguments after `review`. Throws UsageError on anything it does not accept. */
export function parseReviewArgs(args: string[]): ReviewArgs {
  let repo: string | undefined;
  let observational = false;
  let out: string | undefined;
  let cache = DEFAULT_CACHE;
  for (let i = 0; i < args.length; i++) {
    const a = args[i]!;
    const eq = a.indexOf("=");
    const name = eq === -1 ? a : a.slice(0, eq);
    // A flag takes its value inline (--out=dir) or as the next argument (--out dir).
    const takeValue = (): string => {
      if (eq !== -1) return a.slice(eq + 1);
      const v = args[++i];
      if (v === undefined || v.startsWith("--")) throw new UsageError(`${name} needs a value`);
      return v;
    };
    if (name === "--observational" && eq === -1) observational = true;
    else if (name === "--out") out = takeValue();
    else if (name === "--cache") cache = takeValue();
    else if (a.startsWith("-")) throw new UsageError(`unknown flag ${a}`);
    else if (repo === undefined) repo = a;
    else throw new UsageError(`unexpected argument ${a}`);
  }
  if (repo === undefined) throw new UsageError("missing <repo>");
  if (!observational) {
    throw new UsageError("only --observational is implemented; the controlled replay path is not built yet");
  }
  return { repo, out, cache };
}

const NO_DATA =
  "no Entire data found. Run `entire enable` in the source repo, push its entire/checkpoints/v1 branch, and try again.";

function git(repo: string, args: string[]): string {
  const p = Bun.spawnSync(["git", "-c", "core.quotepath=off", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
  if (p.exitCode !== 0) throw new Error(`git ${args[0]} failed: ${p.stderr.toString().trim()}`);
  return p.stdout.toString();
}

interface ScoreContext {
  repo: string;
  head: string;
  headTime: number;
}

const tooYoung = (session_id: string): Outcome => ({
  session_id,
  status: "too_young",
  survival: null,
  reverted: null,
  rework_human: null,
  rework_agent: null,
  unattended: null,
  tests_at_commit: null,
  difficulty: null,
  tercile: null,
});

/**
 * Scores one session from its commit. Sessions without a trailer-linked commit, and commits that are not yet
 * mature, come back too_young with null metrics. Throws when git cannot read the commit.
 */
export function scoreSession(session: ParsedSession, ctx: ScoreContext): Outcome {
  const sha = session.commit_sha;
  if (sha === null) return tooYoung(session.id);
  const depth = Number(git(ctx.repo, ["rev-list", "--count", "--first-parent", `${sha}..${ctx.head}`]).trim());
  const age = ctx.headTime - Number(git(ctx.repo, ["show", "-s", "--format=%ct", sha]).trim());
  if (depth < MIN_DEPTH || age < MIN_AGE_S) return tooYoung(session.id);

  const surv = survival(ctx.repo, [sha], ctx.head);
  const rw = rework(ctx.repo, sha);
  return {
    session_id: session.id,
    status: "mature",
    survival: surv.ratio,
    reverted: reverted(ctx.repo, sha),
    rework_human: rw.human,
    rework_agent: rw.agent,
    unattended: session.n_user_prompts === 1,
    tests_at_commit: null,
    difficulty: null,
    tercile: null,
  };
}

const pct = (x: number) => `${(100 * x).toFixed(1)}%`;

async function stage<T>(n: number, name: Stage, repo: string, work: () => Promise<[T, string]>): Promise<T> {
  return withSpan("TOOL", name, { repo }, async () => {
    const [value, detail] = await work();
    console.log(`[${n}/${STAGES.length}] ${name}: ${detail}`);
    return value;
  });
}

/** Runs the whole review. Resolves to the exit code; writes reports only when every stage succeeds. */
export async function runReview(args: ReviewArgs): Promise<number> {
  const label = repoLabel(args.repo);
  const outDir = resolve(args.out ?? join("reports", reviewSlug(args.repo)));
  const createdAt = new Date().toISOString();
  const reviewId = `${reviewSlug(args.repo)}-${createdAt.replace(/\D/g, "").slice(0, 14)}`;

  await initObs({ workflowName: "roster-review" });
  setSession(reviewId);
  console.log(`roster review ${label} (${reviewId}) → ${outDir}`);
  try {
    return await withSpan("WORKFLOW", "review", { repo: label }, async () => {
      const fetched = await stage(1, "fetch", label, async () => {
        const f = await fetchCheckpoints(args.repo, { cacheDir: resolve(args.cache) });
        return [f, `backend=${f.backend} head=${f.headSha.slice(0, 12) || "none"}`];
      });
      if (fetched.backend === "none") {
        console.error(`roster review: ${NO_DATA}`);
        return 1;
      }
      if (fetched.headSha === "") {
        console.error("roster review: the repo has checkpoints but no HEAD commit to score them against");
        return 1;
      }

      const sessions = await stage(2, "parse", label, async () => {
        const parsed = parseCheckpoints(fetched.repoPath, fetched.backend === "refs" ? "git-refs" : "branch");
        return [parsed, `${parsed.length} sessions`];
      });

      const identities: Identity[] = await stage(3, "identify", label, async () => {
        const ids = sessions.map((s) => identify(s, fetched.repoPath));
        const setups = new Set(ids.map((i) => i.setupId).filter((x): x is string => x !== null)).size;
        const acc = inferenceAccuracy(ids);
        return [ids, `${setups} setups, tag accuracy ${acc === null ? "n/a (no tagged sessions)" : pct(acc)}`];
      });

      const headTime = Number(git(fetched.repoPath, ["show", "-s", "--format=%ct", fetched.headSha]).trim());
      const ctx: ScoreContext = { repo: fetched.repoPath, head: fetched.headSha, headTime };
      const scored = await stage(4, "score", label, async () => {
        const out: Session[] = [];
        const outcomes: Outcome[] = [];
        const failed: string[] = [];
        sessions.forEach((s, i) => {
          const id = identities[i]!;
          const cost = priceSession(s.model, {
            input: s.tokens_in,
            output: s.tokens_out,
            cache_read: s.cache_read,
            cache_write: s.cache_write,
          }).usd;
          out.push({ ...stripParsed(s), setup_id: id.setupId, cost_usd: cost });
          try {
            outcomes.push(scoreSession(s, ctx));
          } catch (err) {
            failed.push(`${s.id}: ${err instanceof Error ? err.message : String(err)}`);
            outcomes.push(tooYoung(s.id));
          }
        });
        const mature = outcomes.filter((o) => o.status === "mature").length;
        return [
          { out, outcomes, failed },
          `${mature} mature, ${outcomes.length - mature} too young${failed.length ? `, ${failed.length} failed` : ""}`,
        ];
      });

      const notes = [
        `${scored.outcomes.filter((o) => o.status === "too_young").length} sessions are too young or have no commit: a session is mature at ≥ ${MIN_DEPTH} first-parent commits and ≥ ${MIN_AGE_S / 3600} h before HEAD`,
        ...scored.failed.map((f) => `could not be scored: ${f}`),
        `${scored.out.filter((s) => s.cost_usd === null).length} sessions have no price (unknown model, or a price that depends on prompt size)`,
        `${scored.out.filter((s) => s.setup_id === null).length} sessions have no setup because their rules hash is unknown`,
      ];
      const review: Review = {
        id: reviewId,
        repo: label,
        created_at: createdAt,
        label: "insufficient_data",
        suspect: null,
        odds_ratio: null,
        ci95: null,
        p_value: null,
        evidence_level: "A",
      };
      const report: ReviewReport = {
        review,
        note:
          "No suspect call. The difficulty-matched Mantel–Haenszel test (DESIGN.md §\"Difficulty and review\") is not part of this command yet, so the setup numbers below are descriptive only.",
        sessions: scored.out,
        outcomes: scored.outcomes,
        notes,
      };
      const written = writeReview(outDir, report);
      console.log(`wrote ${written.join(", ")}`);
      console.log(`label ${review.label} · evidence level ${review.evidence_level}`);
      return 0;
    });
  } finally {
    await flushObs();
  }
}

/** A ParsedSession without the parse-only fields, so sessions.json holds Session rows. */
function stripParsed(s: ParsedSession): Session {
  const { usage_source: _usage, model_source: _model, ...session } = s;
  return session;
}

export const reviewCommand: Command = {
  name: "review",
  summary: "score a repo's agent sessions (--observational)",
  usage: USAGE,
  async run(args) {
    let parsed: ReviewArgs;
    try {
      parsed = parseReviewArgs(args);
    } catch (err) {
      if (!(err instanceof UsageError)) throw err;
      console.error(`roster review: ${err.message}\n\n${USAGE}`);
      return 2;
    }
    return runReview(parsed);
  },
};
