export function maturity(repo: string, sha: string): Censor | null {
  if (!git(repo, ["merge-base", "--is-ancestor", sha, "HEAD"]).ok) return "not_on_head";
  const newer = Number(git(repo, ["rev-list", "--first-parent", "--count", `${sha}..HEAD`]).out);
  const age = commitTimeMs(repo, "HEAD") - commitTimeMs(repo, sha);
  return newer >= MATURE_MIN_COMMITS && age >= MATURE_MIN_AGE_MS ? null : "too_young";
}

/** The session's own cost if ingest priced it, otherwise its summed tokens priced by src/price. */
export function sessionCost(s: Session): number | null {
  if (s.cost_usd !== null) return s.cost_usd;
  return priceSession(s.model, {
    input: s.tokens_in,
    output: s.tokens_out,
    cache_read: s.cache_read,
    cache_write: s.cache_write,
  }).usd;
}

export function scoreSessions(repo: string, sessions: Session[]): ScoredOutcome[] {
  return sessions.map((s) => {
    const base: ScoredOutcome = {
      session_id: s.id,
      status: "too_young",
      survival: null,
      reverted: null,
      rework_human: null,
      rework_agent: null,
      unattended: null,
      tests_at_commit: null,
      difficulty: null,
      tercile: null,
      setup_id: s.setup_id,
      commit_sha: s.commit_sha,
      cost_usd: sessionCost(s),
      censored: "no_commit",
    };
    if (s.commit_sha === null) return base;
    const censored = maturity(repo, s.commit_sha);
    if (censored) return { ...base, censored };
    const r = rework(repo, s.commit_sha);
    return {
      ...base,
      status: "mature",
      censored: null,
      survival: survival(repo, [s.commit_sha], "HEAD").ratio,
      reverted: reverted(repo, s.commit_sha),
      rework_human: r.human,
      rework_agent: r.agent,
      unattended: s.n_user_prompts === 1,
    };
  });
}

export interface SetupAggregate {
  setup_id: string;
  /** All sessions of the setup, mature or censored. */
  sessions: number;
  mature: number;
  too_young: number;
  /** Mature sessions only. */
  reverted: number;
  unattended: number;
  survival_sum: number;
  survival_mean: number | null;
  /** Σ known cost over all sessions; null when no session's cost is known. */
  cost_usd: number | null;
  cost_unknown: number;
  /**
   * Σ cost ÷ Σ survival over mature sessions with a known cost. null when there are none, when
   * Σ survival is 0, or when any mature session's cost is unknown (a partial sum would flatter it).
   */
  cost_per_surviving_change: number | null;
}

// Recomputes the totals in every reports/**/*.json and exits 1 with a diff on any mismatch.
// Rules (applied to every object found, at any depth):
//   total + by_setup            sum(by_setup) = total
//   n + pass + fail + excluded  pass + fail + excluded = n
//   cost_total_usd + cost_by_setup  sum(cost_by_setup) = cost_total_usd (within 0.005)
//   <k>_pct + <k> + n           <k>_pct = 100 * <k> / n (within 0.1 pt)
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";

export type Mismatch = { file: string; path: string; rule: string; expected: number; actual: number };

const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

function sumOf(v: unknown): number | undefined {
  const vals = Array.isArray(v) ? v : isRecord(v) ? Object.values(v) : undefined;
  if (!vals || vals.length === 0 || !vals.every(isNum)) return undefined;
  return vals.reduce((a, b) => a + b, 0);
}

export function checkReport(file: string, data: unknown): Mismatch[] {
  const out: Mismatch[] = [];
  const add = (path: string, rule: string, expected: number, actual: number, tol: number) => {
    if (Math.abs(expected - actual) > tol) out.push({ file, path, rule, expected, actual });
  };
  const walk = (node: unknown, path: string) => {
    if (Array.isArray(node)) return node.forEach((x, i) => walk(x, `${path}[${i}]`));
    if (!isRecord(node)) return;
    if (isNum(node.total)) {
      const s = sumOf(node.by_setup);
      if (s !== undefined) add(`${path}.total`, "sum(by_setup) = total", s, node.total, 1e-9);
    }
    if (isNum(node.n) && isNum(node.pass) && isNum(node.fail) && isNum(node.excluded)) {
      add(`${path}.n`, "pass + fail + excluded = n", node.pass + node.fail + node.excluded, node.n, 1e-9);
    }
    if (isNum(node.cost_total_usd)) {
      const s = sumOf(node.cost_by_setup);
      if (s !== undefined) {
        add(`${path}.cost_total_usd`, "sum(cost_by_setup) = cost_total_usd", s, node.cost_total_usd, 0.005);
      }
    }
    if (isNum(node.n) && node.n > 0) {
      for (const [k, v] of Object.entries(node)) {
        if (!k.endsWith("_pct") || !isNum(v)) continue;
        const base = k.slice(0, -4);
        const count = node[base];
        if (isNum(count)) add(`${path}.${k}`, `${k} = 100 * ${base} / n (within 0.1 pt)`, (100 * count) / node.n, v, 0.1);
      }
    }
    for (const [k, v] of Object.entries(node)) walk(v, `${path}.${k}`);
  };
  walk(data, "$");
  return out;
}

function listJson(dir: string): string[] {
  let entries: string[];
  try {
    entries = readdirSync(dir);
  } catch {
    return [];
  }
  return entries.sort().flatMap((e) => {
    const p = join(dir, e);
    if (statSync(p).isDirectory()) return listJson(p);
    return e.endsWith(".json") ? [p] : [];
  });
}

export function sumcheck(reportsDir: string): { files: number; mismatches: Mismatch[] } {
  const files = listJson(reportsDir);
  const mismatches = files.flatMap((f) => {
    try {
      return checkReport(f, JSON.parse(readFileSync(f, "utf8")));
    } catch (e) {
      return [{ file: f, path: "$", rule: `unreadable JSON: ${(e as Error).message}`, expected: 0, actual: 0 }];
    }
  });
  return { files: files.length, mismatches };
}

export function formatDiff(ms: Mismatch[]): string {
  return ms
    .map((m) => `${m.file} ${m.path}\n  rule:     ${m.rule}\n- expected: ${m.expected}\n+ actual:   ${m.actual}`)
    .join("\n");
}

if (import.meta.main) {
  const dir = process.argv[2] ?? "reports";
  const { files, mismatches } = sumcheck(dir);
  if (mismatches.length) {
    console.error(formatDiff(mismatches));
    console.error(`\nsumcheck FAILED: ${mismatches.length} mismatch(es) in ${files} file(s)`);
    process.exit(1);
  }
  console.log(`sumcheck ok: ${files} file(s) in ${dir}`);
}
### Data model (`.roster/roster.db`, exported to `reports/*.json`)
- **`sessions`:**
  - `id, repo, checkpoint_id, harness, model, rules_hash, setup_id`
  - `tokens_in, tokens_out, cache_read, cache_write, cost_usd, n_user_prompts`
  - `first_prompt, commit_sha, started_at, ended_at, files[], entire_url, source`
- **`outcomes`:** `session_id, status (mature|too_young), survival, reverted, rework_human, rework_agent, unattended, tests_at_commit, difficulty, tercile`
- **`setups`:** `id, harness, model, rules_hash, rules_path, label`
- **`plans`:** `id, review_id, json, rationale, created_at`
- **`replays`:**
  - `id, plan_id, task_session_id, setup_id, attempt, isolation_proof, turns, duration_ms, cost_usd`
  - `hidden_pass, suite_pass, scope_ok, judge_equiv, failure_codes[], verdict, transcript_ref, trace_url`
- **`gate_decisions`:** `id, plan_id, candidate, verdict, reasons[], trace_url`
- **`forward_pairs`:** `task_id, setup_old, setup_new, pass_old, pass_new, cost_old, cost_new, merged, blind_labels, seed`
- **`events`:** an append-only step log. Every step is idempotent, and runs resume from here.

### Coordinator tools
- **Review and planning:** `ingest_repo, get_scorecard, get_difficulty, plan_replays`
- **Replays:** `run_replays, get_replay_results, rerun, classify_failures`
- **Decisions and action:** `propose_rules_candidate, gate, promote, revert, open_pr, book_cfo, verify_cfo_readback`
- **Context:** `query_traces` (neatlogs MCP), `graph_impact` (`entire graph`)

The system prompt includes: *"You decide what to try next. The gate decides what ships. Never claim a result the tools didn't return."* There's a hard stop at `budget_usd`.

### Recovery
Every recovery is a tested path, recorded as a TOOL span with `roster.attempt`.

| Failure | Recovery |
|---|---|
| Clone failure | Retry with a partial clone |
| Branch backend missing | Try the refs |
| Install failure at the parent | Retry with a frozen lockfile, then F6 and resample |
| Harness 429/5xx | Backoff, then the alternate inference profile |
| cfo.ai mismatch | Retry once, then report |
| Promotion regresses on replays | Gate rejection, then the next candidate |
| Promotion loses forward | The stop rule triggers a revert PR |
| Low attribution confidence | Abstain from naming a setup |

### Security
- Public repo code runs only in microVMs.
- No secrets in prompts: session transcripts are public.
- Sandboxes get only scoped, revocable keys.
- Entire shadow branches are never pushed.

